package com.dreamseekers;
import com.dreamseekers.aaroncos.*;
import com.dreamseekers.shadow.*;
import com.solegendary.reignofnether.resources.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.Mob;
import net.minecraftforge.gametest.*;
import java.util.*;
@GameTestHolder(DreamseekersMod.MOD_ID) @PrefixGameTestTemplate(false)
public final class AaroncosReservedGameTests {
 @GameTest(template="aaroncos_unit_arena",batch="aaron_reserved",timeoutTicks=130)
 public static void pairAndBothSkillsValidateRealAuthorityButNeverBindChargeOrSpawn(GameTestHelper h){var f=new AaroncosTestFixture(h,"Reserved");var l=f.hand(false,"Owner",10,1,10);var r=f.hand(true,"Owner",40,1,10);var owner=f.player("Owner");var other=f.player("Foreign");f.ready(l,r).thenExecute(()->{var pair=pair(l,r);h.assertTrue(AaroncosPairService.request(null,pair)==AaroncosPairService.Result.INVALID_REQUEST,"null sender");h.assertTrue(AaroncosPairService.request(other,pair)==AaroncosPairService.Result.NOT_OWNER,"real foreign sender");h.assertTrue(AaroncosPairService.request(owner,pair)==AaroncosPairService.Result.UNAVAILABLE&&AaroncosPairService.request(owner,pair)==AaroncosPairService.Result.UNAVAILABLE,"valid duplicate requests do not establish a pair or consume anything");h.assertTrue(AaroncosPairService.request(owner,new AaroncosPairRequest(2,pair.requestId(),pair.intent(),pair.left(),pair.right()))==AaroncosPairService.Result.INVALID_REQUEST,"future schema");h.assertTrue(AaroncosPairService.request(owner,new AaroncosPairRequest(1,pair.requestId(),pair.intent(),pair.right(),pair.left()))==AaroncosPairService.Result.INVALID_SOURCE,"left right roles cannot be swapped");var wrong=new AaroncosPairRequest.Source(l.getId(),UUID.randomUUID(),0,h.getLevel().dimension().location());h.assertTrue(AaroncosPairService.request(owner,new AaroncosPairRequest(1,pair.requestId(),pair.intent(),wrong,pair.right()))==AaroncosPairService.Result.INVALID_SOURCE,"stale UUID cannot bind by entity ID");var dim=new AaroncosPairRequest.Source(l.getId(),l.getUUID(),AaroncosTestFixture.unit(l).rts().ownershipRevision,net.minecraft.world.level.Level.NETHER.location());h.assertTrue(AaroncosPairService.request(owner,new AaroncosPairRequest(1,pair.requestId(),pair.intent(),dim,pair.right()))==AaroncosPairService.Result.WRONG_DIMENSION,"wrong dimension");for(var m:List.of(l,r)){var request=skill(m);h.assertTrue(ShadowSkillService.request(owner,request)==ShadowSkillService.Result.UNAVAILABLE&&ShadowSkillService.request(other,request)==ShadowSkillService.Result.NOT_OWNER,"each exact typed self skill fails closed after authority");var wrongSkill=new ShadowSkillRequest(1,UUID.randomUUID(),m==l?ShadowSkillRequest.Skill.AARONCOS_RIGHT_SPECIAL:ShadowSkillRequest.Skill.AARONCOS_LEFT_SPECIAL,request.caster(),request.target());h.assertTrue(ShadowSkillService.request(owner,wrongSkill)==ShadowSkillService.Result.INVALID_SOURCE,"side skill type cannot borrow other hand");}var u=AaroncosTestFixture.unit(l);u.setOwnerName(f.owner("Foreign"));u.setOwnerName(f.owner("Owner"));h.assertTrue(AaroncosPairService.request(owner,pair)==AaroncosPairService.Result.STALE_OWNER,"observed owner ABA invalidates old pairing request");h.assertTrue(ShadowEnergyGate.reserve(owner,new ShadowEnergyGate.Reservation(UUID.randomUUID(),owner.getUUID(),10))==ShadowEnergyGate.Result.UNAVAILABLE,"real shadow energy ledger is absent, never free authorization");l.getPersistentData().putBoolean("PairEnabled",true);l.getPersistentData().putBoolean("SkillEnabled",true);h.assertTrue(AaroncosPairService.request(owner,pair(l,r))==AaroncosPairService.Result.UNAVAILABLE,"arbitrary NBT cannot enable provider");}).thenIdle(20).thenExecute(()->{var money=ResourcesServerEvents.resourcesList.stream().filter(x->x.ownerName.equals(f.owner("Owner"))).findFirst().orElseThrow();h.assertTrue(money.food==1000&&money.wood==1000&&money.ore==1000&&money.emerald==1000,"no real ledger writes");h.assertTrue(AaroncosTestFixture.unit(l).getAbilities().get().contains(com.dreamseekers.skill.UnitSkillAbility.AARONCOS_LEFT_PRESS)&&AaroncosTestFixture.unit(r).getAbilities().get().contains(com.dreamseekers.skill.UnitSkillAbility.AARONCOS_RIGHT_SHOCK)&&l.getHealth()==450&&r.getHealth()==420,"no cooldown or effects");h.assertTrue(com.solegendary.reignofnether.unit.UnitServerEvents.getAllUnits().stream().filter(e->e instanceof ControlledAaroncosHand a&&a.getOwnerName().equals(f.owner("Owner"))).count()==2,"no additional free partner");}).thenSucceed();}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_reserved",timeoutTicks=130)
 public static void unpairedDeathAndOwnerChangesNeverAffectOtherHand(GameTestHelper h){var f=new AaroncosTestFixture(h,"Independent");var l=f.hand(false,"Owner",10,1,10);var r=f.hand(true,"Owner",40,1,10);f.ready(l,r).thenExecute(()->{h.assertTrue(l.hurt(l.damageSources().generic(),10)&&r.getHealth()==420,"no invented shared HP");AaroncosTestFixture.unit(l).setOwnerName(f.owner("NewOwner"));h.assertTrue(AaroncosTestFixture.unit(r).getOwnerName().equals(f.owner("Owner")),"no hidden shared ownership");l.hurt(l.damageSources().genericKill(),10000);}).thenWaitUntil(()->h.assertTrue(l.isRemoved(),"left actual40tick death" )).thenExecute(()->h.assertTrue(r.isAlive()&&r.getHealth()==420&&AaroncosTestFixture.unit(r).getOwnerName().equals(f.owner("Owner")),"unpaired foundation death does not delete, revive or mutate other hand")).thenSucceed();}
 @GameTest(template="aaroncos_unit_arena",batch="aaron_reserved",timeoutTicks=120)
 public static void malformedItemBoatMissingRemovedAndUnownedTargetsRemainInert(GameTestHelper h){var f=new AaroncosTestFixture(h,"Malformed");var l=f.hand(false,"Owner",10,1,10);var r=f.hand(true,"Owner",40,1,10);var item=new net.minecraft.world.entity.item.ItemEntity(h.getLevel(),0,0,0,new net.minecraft.world.item.ItemStack(net.minecraft.world.item.Items.DIAMOND));f.place(item,24,1,12);var boat=net.minecraft.world.entity.EntityType.BOAT.create(h.getLevel());f.place(boat,24,1,20);var unowned=f.fox("Temp",24,1,30);unowned.setOwnerName("");var removed=f.fox("Removed",24,1,38);removed.discard();f.ready(l,r,item,boat,unowned).thenExecute(()->{for(var m:List.of(l,r)){var u=AaroncosTestFixture.unit(m);for(int id:new int[]{item.getId(),boat.getId(),Integer.MAX_VALUE,removed.getId(),unowned.getId()})for(var action:List.of(com.solegendary.reignofnether.unit.UnitAction.ATTACK,com.solegendary.reignofnether.unit.UnitAction.FOLLOW))new com.solegendary.reignofnether.unit.UnitActionItem(u.getOwnerName(),action,id,new int[]{m.getId()},net.minecraft.core.BlockPos.ZERO,net.minecraft.core.BlockPos.ZERO).action(h.getLevel());h.assertTrue(m.getTarget()==null&&u.getFollowTarget()==null&&!m.doHurtTarget(item)&&!m.doHurtTarget(boat)&&!m.doHurtTarget(unowned),"malformed raw/remove/unowned targets neither crash nor gain combat/follow capability");u.setOwnerName("");h.assertTrue(!m.doHurtTarget(l==m?r:l),"blank-owner source cannot harm other controlled hand");}}).thenSucceed();}
 static AaroncosPairRequest.Source src(Mob m){return new AaroncosPairRequest.Source(m.getId(),m.getUUID(),AaroncosTestFixture.unit(m).rts().ownershipRevision,m.level().dimension().location());}
 static AaroncosPairRequest pair(Mob l,Mob r){return new AaroncosPairRequest(1,UUID.randomUUID(),AaroncosPairRequest.Intent.ESTABLISH_PAIR,src(l),src(r));}
 static ShadowSkillRequest skill(Mob m){return new ShadowSkillRequest(1,UUID.randomUUID(),m instanceof com.dreamseekers.unit.AaroncosLeftHandUnit?ShadowSkillRequest.Skill.AARONCOS_LEFT_SPECIAL:ShadowSkillRequest.Skill.AARONCOS_RIGHT_SPECIAL,new ShadowSkillRequest.Source(m.getId(),m.getUUID(),AaroncosTestFixture.unit(m).rts().ownershipRevision,m.level().dimension().location()),new ShadowSkillRequest.SelfTarget());}
 @AfterBatch(batch="aaron_reserved") public static void cleanup(ServerLevel l){AaroncosTestFixture.cleanup(l);}
}
